# -*- coding: utf-8 -*-
import os,re
R='D:/repository'
def rd(p):
    try: return open(p,'r',encoding='utf-8',errors='ignore').read()
    except Exception as e: return ''
def grep_file(p, pats):
    t=rd(p)
    if not t: return 'MISSING'
    out=[]
    for pat in pats:
        m=[(i+1,l.strip()[:110]) for i,l in enumerate(t.splitlines()) if re.search(pat,l,re.I)]
        out.append('%s=%d%s'%(pat,len(m),(' @'+'; '.join('%d:%s'%(n,s) for n,s in m[:2])) if m else ''))
    return ' | '.join(out)

