 ('#28 小程序 2048', R+'/小程序', ['2048','main package','exceed max limit']),
]

print('=== targeted dir-level symbol scan ===')
for name,root,pats in checks:
    if pats is None:
        print(name+': see per-file below'); continue
    if not os.path.isdir(root):
        print(name+': NO_DIR '+root); continue
    cnt={p:0 for p in pats}; samples={p:[] for p in pats}
    for dp,dns,fns in os.walk(root):
        dns[:]=[d for d in dns if d not in ('node_modules','dist','.git','playwright-report')]
        for fn in fns:
            if os.path.splitext(fn)[1].lower() not in ('.vue','.js','.ts','.py','.json'): continue
