            for p in pats:
                if re.search(p,t,re.I):
                    cnt[p]+=1
                    if len(samples[p])<2: samples[p].append(os.path.relpath(os.path.join(dp,fn),R).replace('\\','/'))
    print('--- '+name)
    for p in pats: print('   %-24s c=%-4d %s'%(p,cnt[p],'; '.join(samples[p])))

print()
